pygments.util.get_int_opt:
def get_int_opt(options, optname, default=None):
    """As :func:`get_bool_opt`, but interpret the value as an integer."""
    string = options.get(optname, default)
    try:
        return int(string)
    except TypeError:
        raise OptionError(f'Invalid type {string!r} for option {optname}; you must give an integer value')
    except ValueError:
        raise OptionError(f'Invalid value {string!r} for option {optname}; you must give an integer value')

pygments.util.get_bool_opt:
def get_bool_opt(options, optname, default=None):
    """
    Intuitively, this is `options.get(optname, default)`, but restricted to
    Boolean value. The Booleans can be represented as string, in order to accept
    Boolean value from the command line arguments. If the key `optname` is
    present in the dictionary `options` and is not associated with a Boolean,
    raise an `OptionError`. If it is absent, `default` is returned instead.

    The valid string values for ``True`` are ``1``, ``yes``, ``true`` and
    ``on``, the ones for ``False`` are ``0``, ``no``, ``false`` and ``off``
    (matched case-insensitively).
    """
    string = options.get(optname, default)
    if isinstance(string, bool):
        return string
    elif isinstance(string, int):
        return bool(string)
    elif not isinstance(string, str):
        raise OptionError(f'Invalid type {string!r} for option {optname}; use 1/0, yes/no, true/false, on/off')
    elif string.lower() in ('1', 'yes', 'true', 'on'):
        return True
    elif string.lower() in ('0', 'no', 'false', 'off'):
        return False
    else:
        raise OptionError(f'Invalid value {string!r} for option {optname}; use 1/0, yes/no, true/false, on/off')

pygments.util.get_list_opt:
def get_list_opt(options, optname, default=None):
    """
    If the key `optname` from the dictionary `options` is a string,
    split it at whitespace and return it. If it is already a list
    or a tuple, it is returned as a list.
    """
    val = options.get(optname, default)
    if isinstance(val, str):
        return val.split()
    elif isinstance(val, (list, tuple)):
        return list(val)
    else:
        raise OptionError(f'Invalid type {val!r} for option {optname}; you must give a list value')

pygments.util.make_analysator:
def make_analysator(f):
    """Return a static text analyser function that returns float values."""

    def text_analyse(text):
        try:
            rv = f(text)
        except Exception:
            return 0.0
        if not rv:
            return 0.0
        try:
            return min(1.0, max(0.0, float(rv)))
        except (ValueError, TypeError):
            return 0.0
    text_analyse.__doc__ = f.__doc__
    return staticmethod(text_analyse)

pygments.lexer.do_insertions:
def do_insertions(insertions, tokens):
    """
    Helper for lexers which must combine the results of several
    sublexers.

    ``insertions`` is a list of ``(index, itokens)`` pairs.
    Each ``itokens`` iterable should be inserted at position
    ``index`` into the token stream given by the ``tokens``
    argument.

    The result is a combined token stream.

    TODO: clean up the code here.
    """
    insertions = iter(insertions)
    try:
        (index, itokens) = next(insertions)
    except StopIteration:
        yield from tokens
        return
    realpos = None
    insleft = True
    for (i, t, v) in tokens:
        if realpos is None:
            realpos = i
        oldi = 0
        while (insleft and i + len(v) >= index):
            tmpval = v[oldi:index - i]
            if tmpval:
                yield (realpos, t, tmpval)
                realpos += len(tmpval)
            for (it_index, it_token, it_value) in itokens:
                yield (realpos, it_token, it_value)
                realpos += len(it_value)
            oldi = index - i
            try:
                (index, itokens) = next(insertions)
            except StopIteration:
                insleft = False
                break
        if oldi < len(v):
            yield (realpos, t, v[oldi:])
            realpos += len(v) - oldi
    while insleft:
        realpos = (realpos or 0)
        for (p, t, v) in itokens:
            yield (realpos, t, v)
            realpos += len(v)
        try:
            (index, itokens) = next(insertions)
        except StopIteration:
            insleft = False
            break

pygments.formatter._lookup_style:
def _lookup_style(style):
